package vaultor.linked;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/** Disposable tests on the actual local APFS volume, never production profiles. */
public final class MacFilesTests {
 static final byte[] V=new byte[32],C=new byte[32];static{Arrays.fill(V,(byte)2);Arrays.fill(C,(byte)1);}
 static final LinkedStore.Scope S=new LinkedStore.Scope("mac-tests","generation",LinkedStore.Client.LOCAL_DESKTOP_OWNER);
 static int passed;interface Case{void run()throws Exception;}
 static void check(String name,Case test)throws Exception{test.run();System.out.println("PASS "+name);passed++;}
 static void require(boolean v)throws Exception{if(!v)throw new AssertionError();}
 static void refused(Case test)throws Exception{try{test.run();throw new AssertionError("Expected refusal");}catch(IOException expected){}}
 static String sign(byte[] key,String text)throws Exception{var m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key,"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(LinkedStore.utf8(text)));}
 static String grant(LinkedStore store,Path root)throws Exception{String n=UUID.randomUUID().toString();long e=System.currentTimeMillis()+55000;return store.authorizeSelectedRoot(S,root,n,e,sign(C,LinkedStore.consentPayload(S,root,n,e)));}
 static class Fixture implements AutoCloseable {
  final Path dir=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch").toAbsolutePath(),"mac-"),root=Files.createDirectory(dir.resolve("source")),file=root.resolve("文档 😀.md"),journal=dir.resolve("journal");
  LinkedStore store;String cap;LinkedStore.Opened doc;final String original="\ufeff# Guide\r\n\r\nBase paragraph.\r\n\r\n<!-- untouched -->\r\n";
  Fixture(LinkedStore.Faults fault)throws Exception{Files.writeString(file,original);store=new LinkedStore(S,journal,V,C,List.of(dir.resolve("managed")),fault);cap=grant(store,root);doc=store.openLinked(S,cap,file.getFileName().toString());if(!store.readonlyReason(S,doc.document()).isEmpty()){try(var h=NativeFiles.open(file,NativeFiles.READ,7,NativeFiles.OPEN,false)){PracticalMetadata.inspect(h);}throw new AssertionError(store.readonlyReason(S,doc.document()));}}
  String candidate(String text)throws Exception{return store.journalDraft(S,doc.document(),doc.epoch(),1,"{}",LinkedStore.utf8(text),sign(V,LinkedStore.proofPayload(doc.document(),doc.epoch(),1,doc.base().revision(),LinkedStore.utf8(text),"{}")));}
  LinkedStore.Receipt save(String text)throws Exception{return store.saveLinked(S,doc.document(),doc.epoch(),candidate(text),UUID.randomUUID().toString());}
  public void close()throws Exception{store.close();}
 }
 public static void main(String[] args)throws Exception{
  if(args.length==2&&args[0].equals("crash")){Path dir=Path.of(args[1]);try(var store=new LinkedStore(S,dir.resolve("journal"),V,C,List.of(),(phase,op)->{if(phase.equals("replacement-captured-before-record"))Runtime.getRuntime().halt(73);})){String cap=grant(store,dir.resolve("source"));var doc=store.openLinked(S,cap,"文档 😀.md");String text="Crash local";String ticket=store.journalDraft(S,doc.document(),doc.epoch(),1,"{}",LinkedStore.utf8(text),sign(V,LinkedStore.proofPayload(doc.document(),doc.epoch(),1,doc.base().revision(),LinkedStore.utf8(text),"{}")));store.saveLinked(S,doc.document(),doc.epoch(),ticket,UUID.randomUUID().toString());}throw new AssertionError("Crash boundary not reached");}
  Files.createDirectories(Path.of("native/linked-markdown/.scratch"));
  check("APFS registration, identity, ordinary Save and untouched BOM/CRLF bytes",()->{try(var f=new Fixture(null)){String id=f.store.rootVolume(S,f.cap);require(id.startsWith("apfs:"));require(NativeFiles.locateRoot(f.root,id).equals(f.root));String local=f.original.replace("Base paragraph.","Edited paragraph.");var receipt=f.save(local);require(receipt.state().equals("COMMITTED"));require(Files.readString(f.file).equals(local));require(Arrays.equals(f.store.readRecoveryArtifact(S,receipt.operation(),"captured"),LinkedStore.utf8(f.original)));require(!receipt.revision().identity().equals(f.doc.base().revision().identity()));}});
  check("consent proof and owner scope",()->{try(var f=new Fixture(null)){refused(()->f.store.authorizeSelectedRoot(S,f.dir,"nonce",System.currentTimeMillis()+55000,"forged"));refused(()->f.store.openLinked(new LinkedStore.Scope("foreign","generation",S.client()),f.cap,"a.md"));}});
  check("external writer conflict preserves disk and protected draft",()->{try(var f=new Fixture(null)){String ticket=f.candidate("Local");Files.writeString(f.file,"External");var r=f.store.saveLinked(S,f.doc.document(),f.doc.epoch(),ticket,UUID.randomUUID().toString());require(r.state().equals("CONFLICT"));require(Files.readString(f.file).equals("External"));require(f.store.recover(S).stream().anyMatch(x->x.record()!=null&&Arrays.equals(x.record().local(),LinkedStore.utf8("Local"))));}});
  check("symlink and traversal confinement",()->{try(var f=new Fixture(null)){Path outside=Files.createDirectory(f.dir.resolve("outside"));Files.writeString(outside.resolve("x.md"),"outside");Files.createSymbolicLink(f.root.resolve("escape"),outside);Files.createSymbolicLink(f.root.resolve("alias.md"),outside.resolve("x.md"));refused(()->f.store.openLinked(S,f.cap,"escape/x.md"));refused(()->f.store.openLinked(S,f.cap,"alias.md"));refused(()->f.store.openLinked(S,f.cap,"../outside/x.md"));require(Files.readString(outside.resolve("x.md")).equals("outside"));}});
  check("hardlink refuses Save; late outside alias retains captured bytes",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-before-capture"))Files.createLink(op.getParent().getParent().resolve("alias.md"),op.getParent().getParent().resolve("source/文档 😀.md"));})){var r=f.save("Local");require(r.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.dir.resolve("alias.md")).equals(f.original));}try(var f=new Fixture(null)){Files.createLink(f.dir.resolve("outside.md"),f.file);var d=f.store.openLinked(S,f.cap,f.file.getFileName().toString());require(f.store.readonlyReason(S,d.document()).equals("HARDLINKED_FILE"));}});
  check("restart after capture requires explicit reviewed recovery",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-captured"))throw new IOException("INTERRUPTED");})){var r=f.save("Local");require(r.state().equals("RECOVERY_REQUIRED"));require(!Files.exists(f.file));f.store.close();f.store=new LinkedStore(S,f.journal,V,C,List.of(),null);f.cap=grant(f.store,f.root);require(!Files.exists(f.file));var review=f.store.reviewRecovery(S,r.operation(),f.cap);require(review.state().equals("PATH_MISSING"));require(f.store.restoreMissingBase(S,review.ticket()).state().equals("BASE_RESTORED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals(f.original));}});
  check("exclusive publication preserves gap occupant",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-captured"))Files.writeString(op.getParent().getParent().resolve("source/文档 😀.md"),"Outside occupant",StandardOpenOption.CREATE_NEW);})){require(f.save("Local").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Outside occupant"));}});
  check("same-byte replacement and root path reuse refuse old identity",()->{try(var f=new Fixture(null)){Files.move(f.file,f.root.resolve("old.md"));Files.writeString(f.file,f.original);require(f.store.reconcile(S,f.doc.document()).state().equals("DOCUMENT_REPLACED"));Files.move(f.root,f.dir.resolve("old-root"));Files.createDirectory(f.root);refused(()->f.store.reconnect(S,f.cap));}});
  check("unavailable source, restart, retained draft and explicit reauthorization",()->{try(var f=new Fixture(null)){f.candidate("Protected offline draft");f.store.disconnect(S,f.cap);refused(()->f.store.openLinked(S,f.cap,f.file.getFileName().toString()));f.store.close();Path moved=f.dir.resolve("moved");Files.move(f.root,moved);f.store=new LinkedStore(S,f.journal,V,C,List.of(),null);require(f.store.recover(S).stream().anyMatch(r->r.record()!=null&&Arrays.equals(r.record().local(),LinkedStore.utf8("Protected offline draft"))));f.cap=grant(f.store,moved);require(f.store.openLinked(S,f.cap,f.file.getFileName().toString()).base().bytes().length>0);refused(()->NativeFiles.mountedVolume("apfs:00000000-0000-0000-0000-000000000000"));}});
  check("POSIX modes preserved and read-only/xattr refuse direct Save",()->{try(var f=new Fixture(null)){Files.setPosixFilePermissions(f.file,PosixFilePermissions.fromString("rw-r-----"));f.doc=f.store.openLinked(S,f.cap,f.file.getFileName().toString());require(f.save("Local").state().equals("COMMITTED"));require(PosixFilePermissions.toString(Files.getPosixFilePermissions(f.file)).equals("rw-r-----"));Files.setPosixFilePermissions(f.file,PosixFilePermissions.fromString("r--r-----"));var d=f.store.openLinked(S,f.cap,f.file.getFileName().toString());require(!f.store.readonlyReason(S,d.document()).isEmpty());Files.setPosixFilePermissions(f.file,PosixFilePermissions.fromString("rw-------"));Files.getFileAttributeView(f.file,UserDefinedFileAttributeView.class).write("test",java.nio.ByteBuffer.wrap(new byte[]{1}));d=f.store.openLinked(S,f.cap,f.file.getFileName().toString());require(!f.store.readonlyReason(S,d.document()).isEmpty());}});
  check("actual abrupt host exit after capture retains explicit recovery",()->{try(var f=new Fixture(null)){f.store.close();var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"--enable-native-access=ALL-UNNAMED","-Dvaultor.linked.library="+System.getProperty("vaultor.linked.library"),"-cp",System.getProperty("java.class.path"),MacFilesTests.class.getName(),"crash",f.dir.toString()).inheritIO().start();require(child.waitFor()==73);require(!Files.exists(f.file));f.store=new LinkedStore(S,f.journal,V,C,List.of(),null);f.cap=grant(f.store,f.root);var record=f.store.recover(S).stream().filter(r->r.captured()).findFirst().orElseThrow();var review=f.store.reviewRecovery(S,record.operation(),f.cap);require(f.store.restoreMissingBase(S,review.ticket()).state().equals("BASE_RESTORED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals(f.original));}});
  check("concurrent write through retained inode during capture is detected",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-captured"))Files.writeString(op.resolve("captured.md"),"External late writer");})){require(f.save("Local").state().equals("RECOVERY_REQUIRED"));require(!Files.exists(f.file));require(f.store.recover(S).stream().anyMatch(r->r.captured()));}});
  check("replaced publication parent refuses and retains original",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-before-capture")){Path root=op.getParent().getParent().resolve("source");Files.move(root,root.resolveSibling("moved"));Files.createDirectory(root);}})){require(f.save("Local").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.dir.resolve("moved/文档 😀.md")).equals(f.original));}});
  check("extended ACL is read-only; private recovery ACLs remain owner-only",()->{try(var f=new Fixture(null)){var child=new ProcessBuilder("/bin/chmod","+a","everyone allow read",f.file.toString()).start();require(child.waitFor()==0);var doc=f.store.openLinked(S,f.cap,f.file.getFileName().toString());require(!f.store.readonlyReason(S,doc.document()).isEmpty());NativeFiles.checkPrivatePermissions(f.journal);}});
  check("denied publication parent refuses before capture",()->{try(var f=new Fixture(null)){Files.setPosixFilePermissions(f.root,PosixFilePermissions.fromString("r-x------"));try{require(f.save("Local").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals(f.original));}finally{Files.setPosixFilePermissions(f.root,PosixFilePermissions.fromString("rwx------"));}}});
  check("interrupted publication completes metadata only after reviewed inode check",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("replacement-published-before-record"))throw new IOException("INTERRUPTED");})){var r=f.save("Local");require(r.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Local"));var review=f.store.reviewRecovery(S,r.operation(),f.cap);require(f.store.completeLinkedMetadata(S,review.ticket()).state().equals("METADATA_RESTORED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals("Local"));}});
  check("unsupported FIFO cannot block open or escape into editor",()->{try(var f=new Fixture(null)){Path fifo=f.root.resolve("pipe.md");var child=new ProcessBuilder("/usr/bin/mkfifo",fifo.toString()).start();require(child.waitFor()==0);refused(()->f.store.openLinked(S,f.cap,"pipe.md"));}});
  check("create-new recovery export clears inherited ACL before private bytes",()->{try(var f=new Fixture(null)){Path out=Files.createDirectory(f.dir.resolve("export"));var child=new ProcessBuilder("/bin/chmod","+a","everyone allow read,file_inherit,directory_inherit",out.toString()).start();require(child.waitFor()==0);try(var pins=NativeFiles.pin(out);var h=NativeFiles.createPrivateRelative(pins.handle(),"private.md")){NativeFiles.admit(h);NativeFiles.overwrite(h,LinkedStore.utf8("Private evidence"),()->{},()->{});require(PosixFilePermissions.toString(Files.getPosixFilePermissions(out.resolve("private.md"))).equals("rw-------"));}}});
  check("native vnode invalidation",()->{try(var f=new Fixture(null);var pins=NativeFiles.pin(f.root);var watch=new NativeFiles.Notifications(pins)){Files.writeString(f.root.resolve("new.md"),"x");require(watch.poll());}});
  System.out.println("TOTAL "+passed+" passed on "+NativeFiles.volumeIdentity(Path.of(".")));
 }
}
